import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

batch_size = 16
in_channels = 32
out_channels = 16
depth, height, width = 16, 32, 32
kernel_size = 3
stride = 2
padding = 1
min_value = -1.0
divisor = 2.0

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void clamp_divide_fused_kernel(const float* __restrict__ in, float* __restrict__ out, 
                                          float min_val, float div_val, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        val = (val < min_val) ? min_val : val;
        val /= div_val;
        out[idx] = val;
    }
}

torch::Tensor clamp_divide_fused_cuda(torch::Tensor input, float min_val, float div_val) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;
    clamp_divide_fused_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        min_val,
        div_val,
        size
    );
    return output;
}
""";

fused_cpp_source = r"""
torch::Tensor clamp_divide_fused_cuda(torch::Tensor input, float min_val, float div_val);
""";

fused_module = load_inline(
    name="fused_clamp_divide",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["clamp_divide_fused_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    A model that performs a transposed 3D convolution, then applies a fused clamp+divide CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, min_value, divisor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                 stride=stride, padding=padding)
        self.min_value = min_value
        self.divisor = divisor

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_module.clamp_divide_fused_cuda(x, self.min_value, self.divisor)
        return x

def get_inputs():
    return [torch.randn(batch_size, in_channels, depth, height, width)]

def get_init_inputs():
    return [in_channels, out_channels, kernel_size, stride, padding, min_value, divisor]
